-- 034 : RCP BDPM condensé → matrice_medicaments (Cardio DEUST 2A)
-- Généré par sql/ops/cardio_rcp_matrice_gen.mjs — NE PAS éditer à la main.
-- Matrice / référentiel uniquement ; publications DEUST = source cours (035).
-- EI : fréquents ou rares graves. Idempotent (jp_fill sans doublon).
-- =============================================================================

CREATE OR REPLACE FUNCTION pg_temp.jp_ent(p_table text, p_valeur text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_id uuid; v_norm text := jeupharma.normaliser_valeur(p_valeur);
BEGIN
  EXECUTE format('SELECT id FROM jeupharma.%I WHERE valeur_norm = $1 AND actif LIMIT 1', p_table) INTO v_id USING v_norm;
  IF v_id IS NULL THEN
    EXECUTE format('INSERT INTO jeupharma.%I (valeur, valeur_norm) VALUES ($1, $2) RETURNING id', p_table) INTO v_id USING p_valeur, v_norm;
  END IF;
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_fill(p_matrice uuid, p_champ text, p_vals text[])
RETURNS void LANGUAGE plpgsql AS $$
DECLARE v_tbl text; v_jt text; v_fk text; v_id uuid; i int;
BEGIN
  SELECT t.ent, t.jt, t.fk INTO v_tbl, v_jt, v_fk FROM (VALUES
    ('secteurs','secteurs_therapeutiques','matrice_secteurs_therapeutiques','secteur_therapeutique_id'),
    ('ct','classes_therapeutiques','matrice_classes_therapeutiques','classe_therapeutique_id'),
    ('cp','classes_pharmacologiques','matrice_classes_pharmacologiques','classe_pharmacologique_id'),
    ('ind','indications','matrice_indications','indication_id'),
    ('ci','contre_indications','matrice_contre_indications','contre_indication_id'),
    ('ei','effets_indesirables','matrice_effets_indesirables','effet_indesirable_id'),
    ('pre','precautions_emploi','matrice_precautions_emploi','precaution_emploi_id'),
    ('inter','interactions','matrice_interactions','interaction_id'),
    ('surv','surveillances','matrice_surveillances','surveillance_id'),
    ('noms','noms_commerciaux','matrice_noms_commerciaux','nom_commercial_id')
  ) AS t(champ, ent, jt, fk) WHERE t.champ = p_champ;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'champ inconnu %', p_champ; END IF;
  IF p_vals IS NULL THEN RETURN; END IF;
  FOR i IN 1 .. coalesce(array_length(p_vals, 1), 0) LOOP
    v_id := pg_temp.jp_ent(v_tbl, p_vals[i]);
    EXECUTE format(
      'INSERT INTO jeupharma.%I (matrice_id, %I, ordre) SELECT $1, $2, $3 WHERE NOT EXISTS (SELECT 1 FROM jeupharma.%I WHERE matrice_id = $1 AND %I = $2)',
      v_jt, v_fk, v_jt, v_fk) USING p_matrice, v_id, i - 1;
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_matrice_by_norm(p_norm text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_m uuid;
BEGIN
  SELECT m.id INTO v_m FROM jeupharma.matrice_medicaments m
  JOIN jeupharma.dcis d ON d.id = m.dci_id
  WHERE d.valeur_norm = jeupharma.normaliser_valeur(p_norm) AND m.statut = 'publie' LIMIT 1;
  IF v_m IS NULL THEN RAISE EXCEPTION 'fiche publie introuvable norm=%', p_norm; END IF;
  RETURN v_m;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_detail_set(p_matrice uuid, p_valeur text)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  UPDATE jeupharma.matrice_medicaments
  SET detail_pharmacologie_id = pg_temp.jp_ent('details_pharmacologie', p_valeur), updated_at = now()
  WHERE id = p_matrice;
END $$;

DO $mig$
DECLARE
  m uuid;
BEGIN
  -- furosemide (CIS 65449480)
  m := pg_temp.jp_matrice_by_norm('furosemide');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : diurétiques de l’anse, sulfamides, code ATC : C03CA01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Le furosémide est un diurétique puissant et son utilisation est recommandée lorsqu’une diurèse rapide et efficace est requise.', 'Il est utilisé en cas d’urgence ou lorsque le traitement par voie orale n’est pas réalisable.', 'Les indications incluent :', 'Œdèmes et/ou ascites d''origine cardiaque ou hépatique.', 'Œdèmes d''origine rénale (en cas de syndrome néphrotique, le traitement de la maladie sous-jacente est essentiel).', 'Œdème pulmonaire (par exemple en cas d''insuffisance cardiaque aiguë).', 'Crise hypertensive (en plus d''autres mesures thérapeutiques).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Insuffisance rénale avec oligo-anurie réfractaire au furosémide.', 'Insuffisance rénale secondaire à une intoxication par des substances néphrotoxiques ou hépatotoxiques.', 'Insuffisance rénale associée à un coma hépatique.', 'Hypokaliémie sévère, hyponatrémie sévère.', 'Hypovolémie avec ou sans hypotension ou déshydratation.', 'Précoma et coma dus à une encéphalopathie hépatique.', 'Hypersensibilité aux sulfamides (par exemple sulfonylurées ou antibiotiques de la classe des sulfamides).', 'L''usage du furosémide est contre-indiqué pendant l''allaitement (voir rubrique 4.6).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Une surveillance soigneuse est indispensable dans les cas suivants :', 'Obstruction partielle des voies urinaires (par exemple hypertrophie de la prostate).', 'Il faut assurer l''évacuation des urines.', 'Hypotension ou risque élevé de diminution importante de la pression artérielle (sténose artérielle coronarienne ou sténose artérielle cérébrale).', 'Diabète patent ou latent ou anomalie de la glycémie (il faut régulièrement contrôler la glycémie).', 'Goutte et hyperuricémie (il faut régulièrement contrôler l''uricémie).', 'Maladie hépatique ou syndrome hépatorénal (insuffisance rénale liée à une maladie hépatique grave).', 'Hypoprotéinémie (liée à un syndrome néphrotique ; dans ce cas, l''effet du furosémide peut être atténué et son ototoxicité accrue).', 'Administration concomitante de sels de lithium (il faut surveiller la lithiémie, voir rubrique 4.5).', 'Porphyrie aiguë (l''emploi des diurétiques est considéré comme dangereux en cas de porphyrie aiguë et il faut donc être prudent).', 'Une diurèse trop importante peut provoquer une hypotension orthostatique ou des hypotentsions aigues.', 'Les AINS peuvent antagoniser l’effet antidiurétique du furosémide et des autres antidiurétiques.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations déconseillées', '+ Lithium', 'Le furosémide peut réduire l''excrétion du lithium, ce qui provoque une augmentation de la cardiotoxicité et des autres effets toxiques du lithium.', 'Il est donc déconseillé d''utiliser les deux médicaments en même temps.', 'Si cette association est jugée nécessaire, il faut étroitement surveiller la lithiémie et, au besoin, ajuster la posologie de lithium.', '+ Rispéridone', 'Voir la rubrique 4.4, Mises en garde spéciales et précautions d’emploi, concernant la mortalité accrue chez les patients âgés souffrant de démence qui reçoivent de façon concomitante de la rispéridone', 'Associations faisant l''objet de précautions d’emploi', '+ Médicaments ototoxiques', 'Le furosémide peut accentuer l''ototoxicité de certains médicaments, par exemple le cisplatine ou les antibiotiques aminosides tels que kanamycine, gentamicine et tobramycine, en particulier en cas d''insuffisance rénale.', 'Etant donné qu''il peut en résulter des lésions irréversibles, il ne faut associer ces médicaments au furosémide que sur indication médicale justifiée.', '+ Hydrate de chloral']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (≥1/10)', 'Fréquent (≥1/100 à Peu fréquent (≥1/1000 à Rare (≥1/10000 à Très rare (Fréquence inconnue (impossible à évaluer sur la base des données disponibles).', 'Fréquent : Hémoconcentration.', 'Peu fréquent : Thrombopénie.', 'Une thrombopénie peut se manifester notamment par une augmentation de la tendance aux hémorragies.', 'Très rare : Anémie hémolytique, anémie aplasique, agranulocytose.', 'Rare : Réactions anaphylactiques et anaphylactoïdes sévères']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Une surveillance soigneuse est indispensable dans les cas suivants :', 'Diabète patent ou latent ou anomalie de la glycémie (il faut régulièrement contrôler la glycémie).', 'Goutte et hyperuricémie (il faut régulièrement contrôler l''uricémie).', 'Administration concomitante de sels de lithium (il faut surveiller la lithiémie, voir rubrique 4.5).']);

  -- spironolactone (CIS 69594548)
  m := pg_temp.jp_matrice_by_norm('spironolactone');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : diurétique thiazidique et diurétique épargneur potassique en association, code ATC : C03EA04.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle.', 'Œdèmes d’origine rénale, cardiaque et hépatique.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament NE DOIT JAMAIS être utilisé en cas de :', 'hypersensibilité aux substances actives, aux sulfamides ou à l’un des excipients mentionnés à la rubrique 6.1 ;', 'insuffisance rénale sévère ou aiguë notamment : anurie, dysfonctionnement rénal à évolution rapide ;', 'maladie d’Addison ;', 'hyperkaliémie ;', 'stade terminal de l’insuffisance hépatique ;', 'association à d’autres diurétiques épargneurs de potassium (seuls ou associés) tels que : amiloride, canrénoate de potassium, éplérénone, triamtérène sauf s’il existe une hypokaliémie (voir rubrique 4.5) ;', 'association au mitotane (voir rubrique 4.5) ;', 'hypercalcémie importante.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['L’association d’un diurétique épargneur de potassium et d’un natriurétique n’exclut pas la survenue d’une hyperkaliémie ou d’une hypokaliémie.', 'Hypokaliémie', 'Le risque de survenue d’une hypokaliémie (Les sujets présentant un espace QT long sont également à risque, que l’origine en soit congénitale ou iatrogénique.', 'L’hypokaliémie (de même que la bradycardie) agit alors comme facteur favorisant la survenue de troubles du rythme sévères (en particulier des torsades de pointes potentiellement létales).', 'Surveiller la kaliémie lors de l''utilisation concomitante avec d''autres médicaments connus pour augmenter le risque d''hypokaliémie induite par les diurétiques thiazidiques.', 'Hyperkaliémie', 'L’utilisation concomitante de médicaments connus pour provoquer une hyperkaliémie et l’altizide/spironolactone peut entraîner une hyperkaliémie sévère.', 'Toute prescription d’un médicament agissant sur le système rénine-angiotensine-aldostérone est susceptible de provoquer une hyperkaliémie.', 'Avant d’envisager une association de plusieurs médicaments bloquant le système rénine-angiotensine-aldostérone, il faut évaluer soigneusement le rapport bénéfice/risque et l’existence d’alternatives éventuelles.', 'Les principaux facteurs de risque d’hyperkaliémie à prendre en considération sont :', 'diabète, altération de la fonction rénale, âge (> 70 ans) et affections connues à l’origine d’hyperkaliémie ;', 'association avec un ou plusieurs autres médicaments bloquant le système rénine-angiotensine-aldostérone et/ou d’autres médicaments hyperkaliémiants et/ou de suppléments potassiques et de régime riche en potassium.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['LIEES A LA SPIRONOLACTONE', 'L’association de ces médicaments majore le risque d’hyperkaliémie.', 'Pour connaître les risques et les niveaux de contrainte spécifiques aux médicaments hyperkaliémiants, il convient de se reporter aux interactions propres à chaque substance.', 'Certaines substances ne font pas l’objet d’interactions spécifiques au regard de ce risque.', 'Néanmoins, ils peuvent agir comme facteurs favorisants lorsqu’ils sont associés à d’autres médicaments déjà mentionnés dans ce chapitre.', 'Associations contre-indiquées', '+ Autres diurétiques épargneurs de potassium (seuls ou associés) (amiloride, canrénoate de potassium, éplérénone, triamtérène)', 'Hyperkaliémie potentiellement létale, notamment chez l’insuffisant rénal (addition des effets hyperkaliémiants).', 'Contre-indiquée sauf s’il existe une hypokaliémie.', '+ Mitotane', 'Risque de blocage de l’action du mitotane par la spironolactone.', 'La spironolactone peut réduire les concentrations plasmatiques de mitotane chez les patients présentant un carcinome corticosurrénalien traités par le mitotane et ne doit pas être utilisée simultanément au mitotane.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['affections du rein et des voies urinaires : insuffisance rénale aiguë.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L’association d’un diurétique épargneur de potassium et d’un natriurétique n’exclut pas la survenue d’une hyperkaliémie ou d’une hypokaliémie.', 'Hypokaliémie', 'Le risque de survenue d’une hypokaliémie (Les sujets présentant un espace QT long sont également à risque, que l’origine en soit congénitale ou iatrogénique.', 'L’hypokaliémie (de même que la bradycardie) agit alors comme facteur favorisant la survenue de troubles du rythme sévères (en particulier des torsades de pointes potentiellement létales).', 'Surveiller la kaliémie lors de l''utilisation concomitante avec d''autres médicaments connus pour augmenter le risque d''hypokaliémie induite par les diurétiques thiazidiques.']);

  -- eplerenone (CIS 61124589)
  m := pg_temp.jp_matrice_by_norm('eplerenone');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Antagoniste de l’aldostérone, code ATC : C03DA04');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['L''éplérénone est indiquée :']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l''un des excipients mentionnés à la rubrique 6.1.', 'Patients avec une kaliémie > 5,0 mmol/L lors de l''instauration du traitement.', 'Patients avec une insuffisance rénale sévère (DFG 2).', 'Patients avec une insuffisance hépatique sévère (Classe Child-Pugh C).', 'Association avec un inhibiteur de l’enzyme de conversion (IEC) et un antagoniste des récepteurs de l’angiotensine II (ARA II).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Hyperkaliémie', 'En raison du mécanisme d''action, une hyperkaliémie peut survenir sous éplérénone.', 'La kaliémie doit être contrôlée chez tous les patients lors de l’initiation du traitement et lors des modifications de posologie.', 'L''administration de suppléments potassiques après le début du traitement par éplérénone n''est pas recommandée en raison du risque accru d''hyperkaliémie.', 'Une baisse de la kaliémie a été observée en cas de diminution de la posologie d’éplérénone.', 'Une étude a montré que l’association d''hydrochlorothiazide à un traitement par l’éplérénone a contrebalancé l’augmentation de la kaliémie.', 'Le risque d''hyperkaliémie peut augmenter lorsque l''éplérénone est utilisée en association avec un IEC et/ou un ARA II.', 'L''association d''un IEC et d’un ARA II avec l''éplérénone ne doit pas être utilisée (voir rubriques 4.3 et 4.5).', 'Insuffisance rénale', 'Chez les patients présentant une insuffisance rénale, notamment une microalbuminurie diabétique, la kaliémie doit être contrôlée régulièrement.', 'Le risque d''hyperkaliémie augmente avec la diminution de la fonction rénale.', 'Ils doivent donc être traités avec précaution.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Interactions pharmacodynamiques', '+ Diurétiques épargneurs de potassium et suppléments potassiques', 'En raison du risque accru d’hyperkaliémie, l’éplérénone ne doit pas être administrée à des patients recevant d’autres diurétiques épargneurs de potassium ou des suppléments potassiques (voir rubrique 4.3).', 'Les diurétiques épargneurs de potassium peuvent aussi majorer l’effet des médicaments antihypertenseurs et des autres diurétiques.', '+ IEC, ARA II', 'Le risque d''hyperkaliémie peut augmenter lorsque l''éplérénone est utilisée en association avec un IEC et/ou un ARAII.', 'Une surveillance étroite de la kaliémie et de la fonction rénale est recommandée, en particulier chez les patients à risque d’insuffisance rénale, par exemple, les patients âgés.', 'La triple association d''un IEC et d’un ARAII avec l''éplérénone ne doit pas être utilisée (voir rubriques 4.3 et 4.4).', '+ Lithium', 'Aucune étude d’interaction médicamenteuse n’a été conduite avec le lithium.', 'Cependant, chez des patients recevant du lithium, des diurétiques et des inhibiteurs de l’enzyme de conversion (IEC), une toxicité du lithium a été observée (voir rubrique 4.4).', 'L’administration concomitante d’éplérénone et de lithium doit être évitée.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (≥ 1/10)', 'Fréquent (≥ 1/100,', 'Peu fréquent (≥ 1/1 000,', 'Rare (≥ 1/10 000,']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Hyperkaliémie', 'En raison du mécanisme d''action, une hyperkaliémie peut survenir sous éplérénone.', 'La kaliémie doit être contrôlée chez tous les patients lors de l’initiation du traitement et lors des modifications de posologie.', 'L''administration de suppléments potassiques après le début du traitement par éplérénone n''est pas recommandée en raison du risque accru d''hyperkaliémie.', 'Une baisse de la kaliémie a été observée en cas de diminution de la posologie d’éplérénone.']);

  -- naftidrofuryl (CIS 61621776)
  m := pg_temp.jp_matrice_by_norm('naftidrofuryl');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : VASODILATATEUR PERIPHERIQUE, code ATC : C04AX21 (C : Système cardiovasculaire).');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement symptomatique de la claudication intermittente des artériopathies chroniques oblitérantes des membres inférieurs (au stade 2).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit jamais être utilisé dans les cas suivants :', 'Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1,', 'Hyperoxalurie connue,', 'Antécédents de lithiase rénale calcique récidivante.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Des cas d''atteinte hépatique grave, de type cytolytique aigu, ont été signalés.', 'En cas de suspicion d’atteinte hépatique, un dosage des transaminases doit être effectué.', 'Il est recommandé d’arrêter le traitement en cas de symptômes évoquant une atteinte hépatique et en cas d’augmentation même modérée des transaminases.', 'La prise de ce médicament paraît susceptible d''entraîner des modifications de la composition des urines favorisant la formation d''une lithiase rénale oxalocalcique.', 'En effet la teneur en oxalate pour une gélule dosée à 200 mg est de 38 mg.', 'Un apport hydrique suffisant est recommandé pendant le traitement pour maintenir une diurèse abondante.', 'La prise du médicament sans boisson au moment du coucher peut entraîner une œsophagite locale.', 'Il est donc indispensable d''avaler toujours la gélule avec un grand verre d''eau.', 'Le naftidrofuryl ne constitue pas un traitement de l''hypertension artérielle.', 'Ce médicament contient du saccharose.', 'Son utilisation est déconseillée chez les patients présentant une intolérance au fructose, un syndrome de malabsorption du glucose et du galactose ou un déficit en sucrase/isomaltase.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Sans objet.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Affections gastro-intestinales', 'Troubles digestifs (diarrhées, vomissements, douleurs épigastriques).', 'Chez quelques patients ayant pris le médicament sans boisson au moment du coucher, l''arrêt du transit de la gélule a provoqué une œsophagite locale.', 'Des cas d’ulcérations de la muqueuse buccale ont été signalés.', 'Affections hépatobiliaires', 'Des cas d''atteinte hépatique grave, de type cytolytique aigu, ont été signalés (voir rubrique 4.4).']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['En cas de suspicion d’atteinte hépatique, un dosage des transaminases doit être effectué.']);

  -- trimetazidine (CIS 61020245)
  m := pg_temp.jp_matrice_by_norm('trimetazidine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : autre médicament en cardiologie à visée anti-angineuse, code ATC : C01EB15.');
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Maladie de Parkinson, symptômes parkinsoniens, tremblement, syndrome des jambes sans repos et autres anomalies motrices reliées.', 'Insuffisance rénale sévère (Clairance de la créatinine < 30 ml/ min).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['En cas de survenue d’une crise d’angor, une réévaluation de la coronaropathie s’impose, et une adaptation du traitement doit être discutée (traitement médicamenteux et éventuellement revascularisation).', 'La trimétazidine peut induire ou aggraver des symptômes parkinsoniens (tremblement, akinésie, hypertonie), qui doivent être régulièrement recherchés, surtout chez les sujets âgés.', 'En cas de doute, les patients doivent être adressés à un neurologue, pour des examens appropriés.', 'La survenue de troubles du mouvement tels que des symptômes parkinsoniens, un syndrome des jambes sans repos, des tremblements, une instabilité posturale, doit conduire à l’arrêt définitif de la trimétazidine.', 'L’incidence de ces cas est faible et ils sont habituellement réversibles à l’arrêt du traitement.', 'La majorité des patients récupère dans les 4 mois suivant l’arrêt de la trimétazidine.', 'Si les symptômes parkinsoniens persistent plus de 4 mois après l’arrêt du traitement, il faut demander l’avis d’un neurologue.', 'Effets indésirables cutanés graves (EICGs)', 'Au moment de la prescription, les patients doivent être informés des signes et symptômes et doivent faire l’objet d’une surveillance étroite pour détecter ces réactions cutanées.', 'Si des signes et des symptômes évocateurs de ces réactions apparaissent, la trimétazidine doit être arrêtée immédiatement et un traitement alternatif doit être envisagé (le cas échéant).', 'Des chutes peuvent survenir en lien avec une instabilité posturale ou une hypotension artérielle, en particulier chez les patients sous traitement antihypertenseur (voir rubrique 4.8.).', 'La trimétazidine doit être prescrite avec précaution chez les patients pour lesquels une augmentation de l’exposition est attendue :']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Aucune interaction médicamenteuse n’a été identifiée.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (≥1/10) ; fréquent (≥1/100,', 'Fréquent']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Au moment de la prescription, les patients doivent être informés des signes et symptômes et doivent faire l’objet d’une surveillance étroite pour détecter ces réactions cutanées.']);

  -- piribedil (CIS 62551633)
  m := pg_temp.jp_matrice_by_norm('piribedil');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : AGONISTES DOPAMINERGIQUES, code ATC : N04BC08.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de la maladie de Parkinson :', 'soit en monothérapie,', 'soit en association à la dopathérapie d''emblée ou secondairement.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament est contre-indiqué dans les situations suivantes :', 'hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1,', 'collapsus cardio-vasculaire,', 'infarctus du myocarde à la phase aiguë,', 'en association avec les neuroleptiques antiémétiques (voir rubrique 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Dyskinésie :', 'A un stade avancé de la maladie de Parkinson, en association avec la lévodopa, des dyskinésies peuvent survenir pendant l’initiation du traitement par piribedil.', 'Dans ce cas, la dose de piribedil doit être réduite.', 'Hypotension orthostatique :', 'Les agonistes dopaminergiques sont connus pour altérer la régulation systémique de la pression artérielle conduisant à une hypotension orthostatique posturale.', 'Il est recommandé de surveiller la pression artérielle, en particulier au début du traitement, étant donné le risque d’hypotension orthostatique associé à un traitement dopaminergique.', 'Comportement anormal :', 'Un comportement anormal a été rapporté et peut être associé à des manifestations comprenant confusion, agitation, agressivité.', 'Une diminution de la dose ou un arrêt progressif du traitement doivent être envisagés si de tels symptômes apparaissent.', 'Troubles du sommeil', 'Une somnolence et des accès de sommeil d’apparition soudaine ont été rapportés lors du traitement par piribédil particulièrement chez les patients atteints de maladie de Parkinson.', 'Un endormissement soudain pendant les activités quotidiennes, dans certains cas sans prodromes, a été très rarement rapporté.']);
